function removeCountryTrunkDigit(value) {
  if (value.startsWith("00")) {
    return null;
  }

  return value.startsWith("0") ? value.slice(1) : value;
}

export function normalizeNigerianPhone(input) {
  if (typeof input !== "string") {
    return null;
  }

  const cleaned = input.replace(/[\s().-]/g, "");

  if (!/^\+?[0-9]+$/.test(cleaned)) {
    return null;
  }

  let national;

  if (cleaned.startsWith("+")) {
    if (!cleaned.startsWith("+234")) {
      return null;
    }
    national = removeCountryTrunkDigit(cleaned.slice(4));
  } else if (cleaned.startsWith("00234")) {
    national = removeCountryTrunkDigit(cleaned.slice(5));
  } else if (cleaned.startsWith("234")) {
    national = removeCountryTrunkDigit(cleaned.slice(3));
  } else if (cleaned.startsWith("0") && !cleaned.startsWith("00")) {
    national = cleaned.slice(1);
  } else {
    national = cleaned;
  }

  if (national === null || !/^[789][01][0-9]{8}$/.test(national)) {
    return null;
  }

  return `+234${national}`;
}

export function formatNigerianPhone(input) {
  const normalized = normalizeNigerianPhone(input);

  if (normalized === null) {
    return null;
  }

  const national = normalized.slice(4);
  return `0${national.slice(0, 3)} ${national.slice(3, 6)} ${national.slice(6)}`;
}
